cat > lib/refunds.js <<'EOF'
/**
 * Computes a partial refund in cents: `percent` percent of `totalCents`.
 * Always rounds down to the whole cent (finance rule), so a series of partial
 * refunds can never exceed the captured amount. `percent` may have up to two
 * decimals (such as 12.5); it is converted to integer basis points so the
 * arithmetic stays in integers and avoids float error.
 */
export function computeRefund(totalCents, percent) {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new RangeError('totalCents must be a non-negative integer');
  }
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
    throw new RangeError('percent must be between 0 and 100');
  }
  const basisPoints = Math.round(percent * 100);
  return Math.floor((totalCents * basisPoints) / 10000);
}
EOF
cat > test/refunds.test.js <<'EOF'
import assert from 'node:assert/strict';
import test from 'node:test';
import { computeRefund } from '../lib/refunds.js';

test('refunds a percentage of the total in cents', () => {
  assert.equal(computeRefund(1000, 50), 500);
  assert.equal(computeRefund(1000, 100), 1000);
  assert.equal(computeRefund(1000, 0), 0);
});

test('rounds down to the cent, never to nearest', () => {
  assert.equal(computeRefund(999, 50), 499); // 499.5
  assert.equal(computeRefund(1001, 33), 330); // 330.33
  assert.equal(computeRefund(199, 99), 197); // 197.01
  assert.equal(computeRefund(1999, 99.99), 1998); // 1998.80
});

test('handles fractional percents without float error', () => {
  assert.equal(computeRefund(10000, 0.07), 7);
  assert.equal(computeRefund(10000, 12.5), 1250);
});

test('rejects invalid input', () => {
  assert.throws(() => computeRefund(10.5, 10), RangeError);
  assert.throws(() => computeRefund(100, -1), RangeError);
  assert.throws(() => computeRefund(100, 101), RangeError);
});
EOF
